Method.Implementation:
	set cOFFICEPHONE = "495"
	set cOFFICEADD = "50450836"
	//do source.XMLExportToString(.str)
	//set ^IHC("MsprProviderToGenericHl7","MsprSource")=str
	try{
		set mMemInfo=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.names.Item
	    set countNames=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.names.Item.Count()
	    //set ^IHC("MsprProviderToGenericHl7","CountNames1")=countNames
	}catch{ set countNames=0}
	set namIndex=1
	for i=1:1:countNames {
		//set ^IHC("MsprProviderToGenericHl7","lastNAme")=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.names.Item.GetAt(i).lastName.content
		set nmType=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.names.Item.GetAt(i).nameTypeCid.ncid
		If (nmType'="188"){
			 set ln=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.names.Item.GetAt(i).lastName.content
			 set fn=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.names.Item.GetAt(i).firstName.content
			 set mn=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.names.Item.GetAt(i).middleName.content
			 set sfx=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.names.Item.GetAt(i).suffix.content
			 set pfx=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.names.Item.GetAt(i).title.content
			 set deg=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.names.Item.GetAt(i).degree.content
			 Set tSC1=target.SetValueAt(ln,"MFEgrp("_(1)_").STF:StaffName("_(namIndex)_").familylastname","set","")
 			 Set tSC1=target.SetValueAt(fn,"MFEgrp("_(1)_").STF:StaffName("_(namIndex)_").givenname","set","")
 			 Set tSC1=target.SetValueAt(mn,"MFEgrp("_(1)_").STF:StaffName("_(namIndex)_").middleinitialorname","set","")
 			 Set tSC1=target.SetValueAt(sfx,"MFEgrp("_(1)_").STF:StaffName("_(namIndex)_").suffix","set","")
 			 Set tSC1=target.SetValueAt(pfx,"MFEgrp("_(1)_").STF:StaffName("_(namIndex)_").prefix","set","")
 			 Set tSC1=target.SetValueAt(deg,"MFEgrp("_(1)_").STF:StaffName("_(namIndex)_").degree","set","")
 			 Set tSC1=target.SetValueAt(nmType,"MFEgrp("_(1)_").STF:StaffName("_(namIndex)_").nametypecode","set","")
 			 set namIndex=namIndex+1
 		}
	}
	//try{
		set sex=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.sex.content
		//set ^IHC("MsprProviderToGenericHl7","MsprSex")=sex
	//}catch{ set sex=""}
	Set tSC1=target.SetValueAt(sex,"MFEgrp("_(1)_").STF:Sex","set","")
	try {
		set dob=""
		set dob=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.dateOfBirth.birthDate.content
		set dob=$replace(dob,"Z","0")
	}catch{}
	Set tSC1=target.SetValueAt(dob,"MFEgrp("_(1)_").STF:DateTimeOfBirth","set","")
	// Populate Phone
	try {
		set countPhones=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.phones.Item.Count()
	}catch{set countPhones=0}
	set phnIndex=1
	for i=1:1:countPhones {
		set phoneType=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.phones.Item.GetAt(i).phoneTypeCid.ncid
		set localNum=$Replace(source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.phones.Item.GetAt(i).localNumber.content,$c(0),"")
		If ((phoneType=cOFFICEPHONE)&&(localNum'="")){
			set countryCode=$Replace(source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.phones.Item.GetAt(i).countryCode.content,$c(0),"")
			set areaCode=$replace(source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.phones.Item.GetAt(i).areaCode.content,$c(0),"")
			set extension=$Replace(source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.phones.Item.GetAt(i).extension.content,$c(0),"")
			Set tSC1=target.SetValueAt(countryCode,"MFEgrp("_(1)_").STF:Phone("_(phnIndex)_").CountryCode","set","")
			Set tSC1=target.SetValueAt(areaCode,"MFEgrp("_(1)_").STF:Phone("_(phnIndex)_").Areacitycode","set","")
			Set tSC1=target.SetValueAt(localNum,"MFEgrp("_(1)_").STF:Phone("_(phnIndex)_").Phonenumber","set","")
			Set tSC1=target.SetValueAt(extension,"MFEgrp("_(1)_").STF:Phone("_(phnIndex)_").Extension","set","")
			Set tSC1=target.SetValueAt(phoneType,"MFEgrp("_(1)_").STF:Phone("_(phnIndex)_").anytext","set","")
			set fullNum=areaCode_localNum
			If (countryCode'=""){
				set fullNum=countryCode_" "_fullNum
			}
			If (extension'=""){
				set fullNum=fullNum_"x"_extension
			}
			Set tSC1=target.SetValueAt(fullNum,"MFEgrp("_(1)_").STF:Phone("_(phnIndex)_").phonenumber1","set","")
			set phnIndex=phnIndex+1
			quit
		}


	}
	//Populate Address
	try {
		set countAddr=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.addresses.Item.Count()
	}catch {set countAddr=0}
	set addrIndex=1
	for i=1:1:countAddr {
		set addrType=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.addresses.Item.GetAt(i).addressTypeCid.ncid
		If (addrType=cOFFICEADD){
			set street1=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.addresses.Item.GetAt(i).street1.content
			set street2=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.addresses.Item.GetAt(i).street2.content
			set city=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.addresses.Item.GetAt(i).city.content
			set state=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.addresses.Item.GetAt(i).state.content
			set zip=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.addresses.Item.GetAt(i).postCode.content
			set country=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.addresses.Item.GetAt(i).country.content
			Set tSC1=target.SetValueAt(street1,"MFEgrp("_(1)_").STF:OfficeHomeAddress("_addrIndex_").streetaddress","set","")
			Set tSC1=target.SetValueAt(street2,"MFEgrp("_(1)_").STF:OfficeHomeAddress("_addrIndex_").otherdesignation","set","")
			Set tSC1=target.SetValueAt(city,"MFEgrp("_(1)_").STF:OfficeHomeAddress("_addrIndex_").city","set","")
			Set tSC1=target.SetValueAt(state,"MFEgrp("_(1)_").STF:OfficeHomeAddress("_addrIndex_").stateorprovince","set","")
			Set tSC1=target.SetValueAt(zip,"MFEgrp("_(1)_").STF:OfficeHomeAddress("_addrIndex_").ziporpostalcode","set","")
			Set tSC1=target.SetValueAt(country,"MFEgrp("_(1)_").STF:OfficeHomeAddress("_addrIndex_").country","set","")
			Set tSC1=target.SetValueAt(addrType,"MFEgrp("_(1)_").STF:OfficeHomeAddress("_addrIndex_").addresstype","set","")
			set addrIndex=addrIndex+1
			quit
		}
	}
	// Affiliations
	try {
		set countAffiliations=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.affiliations.Item.Count()
	}catch {set countAffiliations=0}
	set actIndex=1
	set inactIndex=1
	for i=1:1:countAffiliations {
		set fac=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.affiliations.Item.GetAt(i).entityNcid.ncid
		set actDate=$replace(source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.affiliations.Item.GetAt(i).startDate.content,$c(0),"")
		If (actDate'=""){
			set actDate=$REPLACE(actDate,"Z","0")
			Set tSC1=target.SetValueAt(actDate,"MFEgrp("_(1)_").STF:InstitutionActivationDate("_(actIndex)_").date","set","")
			Set tSC1=target.SetValueAt(fac,"MFEgrp("_(1)_").STF:InstitutionActivationDate("_(actIndex)_").institutionname.identifier","set","")
			set actIndex=actIndex+1
		}
		set inactDate=$replace(source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.affiliations.Item.GetAt(i).endDate.content,$c(0),"")
		If (inactDate'=""){
			set inactDate=$REPLACE(inactDate,"Z","0")
			Set tSC1=target.SetValueAt(inactDate,"MFEgrp("_(1)_").STF:InstitutionInactivationDate("_(inactIndex)_").date","set","")
			Set tSC1=target.SetValueAt(fac,"MFEgrp("_(1)_").STF:InstitutionInactivationDate("_(inactIndex)_").institutionname.identifier","set","")
			set inactIndex=inactIndex+1
		}
	}
	quit $$$OK

set phoneNumber = "" 
try {
	set countPhones=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.phones.Item.Count()
}catch{set countPhones=0}
set phnIndex=1
for i=1:1:countPhones {
	set phoneType=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.phones.Item.GetAt(i).phoneTypeCid.ncid
	set localNum=$replace(source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.phones.Item.GetAt(i).localNumber.content,$c(0),"")
	set areaCode=$replace(source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.phones.Item.GetAt(i).areaCode.content,$c(0),"")

	If ((phoneType="50450954")&&(localNum'="")){
		set phoneNumber=areaCode_localNum
		quit
	}
}
quit phoneNumber

 Set tSC1=target.SetValueAt("CORPROV","MSH:SendingApplication","set","")
