			 Set fullNum=target.GetValueAt("MFEgrp("_(1)_").STF:Phone("_(1)_").phonenumber1")
			 Set areaCode=target.GetValueAt("MFEgrp("_(1)_").STF:Phone("_(1)_").Areacitycode")
			 Set localNum=target.GetValueAt("MFEgrp("_(1)_").STF:Phone("_(1)_").Phonenumber") 

			 Set tSC1=target.SetValueAt(fullNum,"MFEgrp("_(1)_").STF:Phone("_(2)_").phonenumber1","set","")
			 Set tSC1=target.SetValueAt(areaCode,"MFEgrp("_(1)_").STF:Phone("_(2)_").Areacitycode","set","")
			 Set tSC1=target.SetValueAt(localNum,"MFEgrp("_(1)_").STF:Phone("_(2)_").Phonenumber","set","")
			 Set tSC1=target.SetValueAt("194","MFEgrp("_(1)_").STF:Phone("_(2)_").anytext","set","") 

	 	}
	 }
	 //set tSC=..MapMSPRLicenses(msprResponse,.target)

 }
 If (pSendEmailAddress="1"){
	 set emailAddress=source.PROVIDERDEMOGRAPHIC.ADVPROVIDERINTERNETEMAILADDRTXT.content
	 Set tSC1=target.SetValueAt(emailAddress,"MFEgrp("_(1)_").STF:EMailAddress("_(1)_")","set","")
 }
 //Specialty ID count
 try{
	 set countSpecId=source.PROVIDERDEMOGRAPHIC.ADVPRVDRSPCLTYSPCLTYID.Count()

}catch{ set countNames=0}
set namIndex=1
for specIndex=1:1:countSpecId {
	set spcltyId=source.PROVIDERDEMOGRAPHIC.ADVPRVDRSPCLTYSPCLTYID.GetAt(specIndex).content
	set spcltyRep=""
	set spcltyNcid=""
	set hddObj =  ##class(IHC.ITF.ITFCOMMON.HDD.Interface.Utility).GetHddObject(hddSpecNcid,"ADVPRVDRSPCLTYSPCLTYID"_spcltyId)	  
	if ((hddObj '="")&&(hddObj.NCID'="")){
  		set spcltyNcid=hddObj.NCID
  		//Get Rep
  		set hddObj =  ##class(IHC.ITF.ITFCOMMON.HDD.Interface.Utility).GetHddObject(hddSpecRep,"ADVPRVDRSPCLTYSPCLTYID"_spcltyNcid)	  
		if ((hddObj '="")&&(hddObj.Rep'="")){
			set spcltyRep=hddObj.Rep
		}

	}
	Set tSC1=target.SetValueAt(spcltyRep,"MFEgrp("_(1)_").PRA:Specialty("_(specIndex)_").specialtyname","set","")
	If (source.PROVIDERDEMOGRAPHIC.ADVPROVIDERCREDENTIALED.content'="Y"){
		Set tSC1=target.SetValueAt(spcltyNcid,"MFEgrp("_(1)_").PRA:PractitionerCategory("_(specIndex)_")","set","")
	}

}

 quit $$$OK

set npi=""
set oIndx=1
Set tSC1=target.SetValueAt(proId,"MFEgrp("_(1)_").PRA:PractitionerIDNumbers("_(oIndx)_").IDnumberST","set","")
Set tSC1=target.SetValueAt("50450667","MFEgrp("_(1)_").PRA:PractitionerIDNumbers("_(oIndx)_").typeofIDnumberIS","set","")
set oIndx=oIndx+1
try{
	set midCnt=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.genericMemberIds.Item.Count()
}catch{ set midCnt=0}
for i=1:1:midCnt {
	set idTypeNcid=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.genericMemberIds.Item.GetAt(i).idTypeNcid.ncid

	If (idTypeNcid="510097850"){
		set npi=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.genericMemberIds.Item.GetAt(i).idValue.content

	}else{
		set asaNcid=$replace(source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.genericMemberIds.Item.GetAt(i).assigningAuthorityNcid.ncid,$c(0),"")
		If (asaNcid'=""){
			set idValue=source.ServiceMessage.MsprInfo.dataRecord.msprRecords.Item.GetAt(1).memberInfo.genericMemberIds.Item.GetAt(i).idValue.content
			Set tSC1=target.SetValueAt(idValue,"MFEgrp("_(1)_").PRA:PractitionerIDNumbers("_(oIndx)_").IDnumberST","set","")
			Set tSC1=target.SetValueAt(idTypeNcid,"MFEgrp("_(1)_").PRA:PractitionerIDNumbers("_(oIndx)_").typeofIDnumberIS","set","")
			Set tSC1=target.SetValueAt(asaNcid,"MFEgrp("_(1)_").PRA:PractitionerIDNumbers("_(oIndx)_").stateotherqualifyinginfo","set","")
			set oIndx=oIndx+1
		}
	}

}
Set tSC1=target.SetValueAt(npi,"MFEgrp("_(1)_").ZPI:Field3","set","")

quit $$$OK
